/**
 * The single illustrative example dataset. It is generated by the curated knowledge-base
 * engine for a hypothetical business. It is NOT live research and is always labelled as
 * an illustrative example in the UI.
 */
import type { Analysis } from "./schema";
import { normalizeInput } from "./engine/normalize";
import { runKnowledgeBase } from "./engine/kb-engine";
import { baseGuardrails } from "./knowledge/guardrails";

export const DEMO_ID = "demo";

export const DEMO_INPUT = {
  businessName: "Example Excavation Co. (illustrative)",
  website: "",
  industry: "Excavation contractor",
  serviceArea: "Sarnia, Ontario and Lambton County",
  idealCustomer: "Homeowners, property managers, general contractors, home builders, commercial property owners",
  services: "Excavation, grading, drainage, demolition, foundation excavation, septic installation",
  projectValue: "",
  targetIndustries: "",
  growthPriority: "recurring" as const,
  existingReferrals: "",
  expansionMarkets: "",
};

let cached: Analysis | null = null;

export function getDemoAnalysis(): Analysis {
  if (cached) return cached;
  const profile = normalizeInput(DEMO_INPUT);
  const kb = runKnowledgeBase(profile);
  cached = {
    id: DEMO_ID,
    createdAt: "2026-01-01T00:00:00.000Z",
    isDemo: true,
    profile,
    engine: {
      mode: "demo",
      provider: null,
      model: null,
      archetypeId: kb.match.archetype.id,
      archetypeLabel: kb.match.archetype.label,
      matchConfidence: kb.match.confidence,
      notes: ["Illustrative example for a hypothetical business. It is not live research and names no real organisations."],
      version: "demo",
    },
    categories: kb.categories,
    assumptions: kb.assumptions,
    guardrails: [...kb.guardrails, ...baseGuardrails(profile)],
  };
  return cached;
}
